const path = require('path');
const fs = require('fs-extra');

async function copyAssets() {
    const targetDirectory = './dist/assets/';

    // Check if the folder we want to push to already exists, so we can clear it out.
    if (fs.existsSync(targetDirectory)) { await fs.promises.rm(targetDirectory, { recursive: true, force: true }); }

    // Copy both Core and Regional Assets
    const coreFrom = path.resolve(__dirname, `../src/assets`);

    fs.cpSync(coreFrom, targetDirectory, { filter: src => path.extname(src) !== '.ts', recursive: true, force: true });
}

copyAssets();